import{_ as o,l as i,o as a,c as n,v as t,p as l,x as r,d,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"复位策略","description":"","frontmatter":{"title":"复位策略","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/reset-strategy.md","filePath":"cs/reset-strategy.md","lastUpdated":1789023840000}'),h={name:"cs/reset-strategy.md"};function _(E,e,m,A,u,F){const s=i("Mermaid");return a(),n("div",null,[e[1]||(e[1]=t('<h1 id="复位策略" tabindex="-1">复位策略 <a class="header-anchor" href="#复位策略" aria-label="Permalink to &quot;复位策略&quot;">​</a></h1><div class="epigraph"><p>复位要让状态机进已知态，但释放沿必须相对于时钟可预测：异步断言、同步释放是常见折中，否则恢复时间与偏斜会在上电时制造幽灵状态。</p><footer>—— 据 Cummings, Synthesizable Finite State Machine Design Techniques Using the New SystemVerilog 3.0, SNUG；Harris and Harris, Digital Design and Computer Architecture 整理</footer></div><p><a href="/cs/clock-skew-cts">上一课</a>让每个 FF 的时钟到达时间变成数字。复位是另一根全局网：它也要树，也有偏斜。缺口是<strong>复位策略</strong>——异步还是同步、如何释放——否则 STA 的恢复/移除检查与上电行为对不齐。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>异步复位：<code>always @(posedge clk or negedge rst_n)</code>，断言立刻清 Q，不依赖时钟，上电友好。释放时 <code>rst_n</code> 相对 <code>clk</code> 若落在恢复窗口，FF 亚稳——与<a href="/cs/setup-hold">建立保持</a>同类窗口，名字叫 recovery/removal。同步复位：只在边沿采样复位，释放自然对齐时钟，但断言也要等时钟，时钟未振时清不掉。缺口不是再讲 CTS，而是这两类复位如何接、如何把释放同步化。</p><p>常用：异步断言、经两级 FF <strong>同步释放</strong>，再送到各异步复位脚。复位树同样要 CTS 一类平衡。</p><h3 id="每个寄存器都异步复位不是免费" tabindex="-1">每个寄存器都异步复位不是免费 <a class="header-anchor" href="#每个寄存器都异步复位不是免费" aria-label="Permalink to &quot;每个寄存器都异步复位不是免费&quot;">​</a></h3><p>面积、布线、复位树功耗、以及「故意不复位」的流水线数据寄存器（下一拍会被有效数据覆盖）。全芯片异步复位会让综合插入大量复位端口。把「好设计=处处复位」当成教条，时序与布线会胀。</p><p><span class="marginnote">Cummings 的 FSM 与复位风格文章是 RTL 实践来源。Harris 给出异步复位模板。本课不把上电复位芯片内部模拟电路画完。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>外部 <code>rst_n</code> 异步来。同步器（两级 FF，时钟已稳定后）产生内部 <code>rst_n_sync</code>。消费端：异步复位脚接 <code>rst_n_sync</code>，释放已与时钟同源。需要完全同步复位的路径只用数据端 MUX。扫描测试时复位可被 DFT 改接，后课扫描链再钉。</p>',11)),(a(),l(p,null,{default:r(()=>[c(s,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20EXT%5B%22%E5%A4%96%E9%83%A8%E5%A4%8D%E4%BD%8D%22%5D%20--%3E%20SYNC%5B%22%E4%B8%A4%E7%BA%A7%E5%90%8C%E6%AD%A5%E9%87%8A%E6%94%BE%22%5D%0A%20%20SYNC%20--%3E%20FF%5B%22FF%20%E5%BC%82%E6%AD%A5%E5%A4%8D%E4%BD%8D%E8%84%9A%22%5D%0A%20%20FF%20--%3E%20FSM%5B%22%E5%B7%B2%E7%9F%A5%E5%88%9D%E6%80%81%22%5D%0A%20%20SYNC%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E8%B7%A8%E6%97%B6%E9%92%9F%E5%9F%9F%20FIFO%22%5D%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<p>多时钟域：每个域自己同步释放，不要把 A 域已释放的复位直接异步灌进 B 域。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>下一课异步 FIFO 处理数据跨域；复位跨域同样要按域同步，否则 FIFO 指针的初值在两边不是「同时」变零。STA：声明复位为时序检查对象（recovery），或把异步复位路径设为假路径并依赖同步释放结构——约束必须匹配 RTL。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲上电复位（POR）带隙电路，不把看门狗当成复位策略的全部。不讨论部分复位（只复位外设子系统）的电源域细节，留给后课功耗/电源。</p><p>后课默认：复位异步断言、同步释放；每时钟域各有同步后的复位。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>异步断言方便上电；释放必须相对时钟过恢复窗口。</li><li>两级同步释放是常用结构；复位树也有偏斜。</li><li>跨域复位与跨域数据一样要同步。</li><li>出处：Cummings SNUG；Harris and Harris。</li></ul>',8))])}const g=o(h,[["render",_]]);export{T as __pageData,g as default};
